'use strict';
window.IlkerAccess=(()=>{
 let api,fail,signedOut,user,activeDialog,auditOffset=0,desiredLanguage=null,syncing=false,generation=0;
 const $=s=>document.querySelector(s);
 const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
 const staticText=(tag,key,cls)=>{const e=el(tag,key,cls);window.IlkerAdminI18n?.bind(e,key);return e;};
 const bind=(node,render)=>window.IlkerAdminI18n.bind(node,render);
 const role=value=>value==='owner'?'Владелец':'Ресепшен';
 function scheduleLanguage(value){
  if(!user||!api)return;desiredLanguage=value;if(syncing)return;syncing=true;const current=generation;
  (async()=>{try{while(current===generation&&desiredLanguage){const next=desiredLanguage;desiredLanguage=null;const result=await api('/api/admin/account/language',{language:next});if(current!==generation)return;user=result.user;}}catch(error){if(current===generation)fail(error);}finally{if(current===generation){syncing=false;if(desiredLanguage)scheduleLanguage(desiredLanguage);}}})();
 }
 document.addEventListener('adminlanguagechange',event=>scheduleLanguage(event.detail.language));
 function button(text,handler,primary=false){const b=staticText('button',text,primary?'button primary':'text-button');b.type='button';b.addEventListener('click',async()=>{b.disabled=true;try{await handler();}catch(e){fail(e);}finally{b.disabled=false;}});return b;}
 function field(text,type,value=''){const label=staticText('label',text),input=el('input');input.type=type;input.value=value;input.setAttribute('aria-label',text);window.IlkerAdminI18n?.bind(input,text,'aria-label');if(type==='password'){input.maxLength=200;input.autocomplete='new-password';}label.append(input);return {label,input};}
 function modal(title){if(activeDialog)activeDialog.close();const d=el('dialog',undefined,'reception-dialog'),form=el('form'),error=el('p',undefined,'reception-error');error.setAttribute('role','alert');form.append(staticText('h2',title),error);d.append(window.IlkerAdminI18n?.makeSwitcher()||el('span'),form);let errorKey='';const renderError=()=>{error.textContent=window.IlkerAdminI18n?.t(errorKey)||errorKey;};document.addEventListener('adminlanguagechange',renderError);d.addEventListener('close',()=>{document.removeEventListener('adminlanguagechange',renderError);d.remove();if(activeDialog===d)activeDialog=null;});document.body.append(d);activeDialog=d;d.showModal();return {d,form,error,setError:key=>{errorKey=key;renderError();}};}
 function submit(view,fields,label,run){const save=staticText('button',label,'button primary');save.type='submit';view.form.append(fields,save,button('Закрыть',()=>view.d.close()));view.form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;fields.disabled=true;view.setError('');try{await run();view.d.close();}catch(error){view.setError(error.status?error.message:'Ответ не получен. Проверьте состояние перед повтором.');if(error.status===401){view.d.close();signedOut();}}finally{save.disabled=false;fields.disabled=false;}});}
 function proofField(){const proof=field('Ваш текущий пароль','password');proof.input.required=true;proof.input.autocomplete='current-password';return proof;}
 async function password(){const view=modal('Смена пароля'),fields=el('fieldset',undefined,'reception-fields'),current=proofField(),next=field('Новый пароль','password'),repeat=field('Повторите новый пароль','password');next.input.minLength=repeat.input.minLength=12;next.input.required=repeat.input.required=true;fields.append(current.label,next.label,repeat.label,staticText('p','После смены пароля все ваши устройства выйдут из аккаунта. Push потребуется включить снова.','small-note'));
  submit(view,fields,'Изменить пароль',async()=>{if(next.input.value!==repeat.input.value)throw Object.assign(new Error('Пароли не совпадают.'),{status:400});await api('/api/admin/account/password',{currentPassword:current.input.value,newPassword:next.input.value});signedOut();});
 }
 async function revoke(device=null){const view=modal(device?'Завершить сессию':'Выйти на всех устройствах'),fields=el('fieldset',undefined,'reception-fields'),proof=proofField();fields.append(proof.label,staticText('p',device?'Выбранное устройство потребуется авторизовать снова.':'Все сессии будут завершены; Push отключится до повторного включения.','small-note'));submit(view,fields,'Подтвердить',async()=>{const data=await api('/api/admin/account/revoke',{id:device?.id,all:!device,currentPassword:proof.input.value});if(data.signInRequired)signedOut();else await render();});}
 async function editUser(row=null){const view=modal(row?'Доступ сотрудника':'Новый сотрудник'),fields=el('fieldset',undefined,'reception-fields'),name=field('Имя сотрудника','text',row?.display_name),login=field('Логин','text',row?.login),next=field(row?'Новый пароль сотрудника (если нужно)':'Пароль сотрудника','password'),proof=proofField();login.input.required=true;login.input.autocomplete='off';login.input.pattern='[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}';login.input.maxLength=40;name.input.maxLength=80;next.input.minLength=12;next.input.required=!row;
  const roleLabel=staticText('label','Роль'),select=el('select');select.setAttribute('aria-label','Роль');window.IlkerAdminI18n?.bind(select,'Роль','aria-label');for(const value of ['reception','owner']){const option=staticText('option',role(value));option.value=value;select.append(option);}select.value=row?.role||'reception';roleLabel.append(select);
  const active=field('Доступ разрешён','checkbox');active.input.checked=row?Boolean(row.active):true;fields.append(name.label,login.label,roleLabel,active.label,next.label,proof.label,staticText('p','При отключении, смене роли или пароля сессии и Push сотрудника отзываются.','small-note'));
  submit(view,fields,'Сохранить доступ',async()=>{await api('/api/admin/users',{id:row?.id,revision:row?.revision,login:login.input.value,displayName:name.input.value,role:select.value,active:active.input.checked,newPassword:next.input.value||undefined,currentPassword:proof.input.value});await render();});
 }
 async function audit(){const view=modal('Журнал действий'),data=await api('/api/admin/audit?offset='+auditOffset);for(const row of data.rows){const card=el('article',undefined,'appointment');card.append(bind(el('strong'),t=>t('audit.'+row.action)),bind(el('p'),(_,lang)=>`${new Date(row.created_at).toLocaleString(lang,{timeZone:'Asia/Baku'})} · ${row.actor}`),bind(el('p'),t=>`${t('entity.'+row.entity_type)} · ${row.entity_id}`),(()=>{const details=el('details');details.append(staticText('summary','Технические детали'),el('pre',row.details_json,'access-details'));return details;})());view.form.append(card);}const tools=el('div',undefined,'action-row');const prev=button('Назад',()=>{auditOffset=Math.max(0,auditOffset-50);return audit();}),next=button('Следующие 50',()=>{auditOffset+=50;return audit();});prev.disabled=auditOffset===0;next.disabled=data.rows.length<50;tools.append(prev,next,button('Закрыть',()=>view.d.close()));view.form.append(tools);}
 async function recoveryEmail(){const view=modal('Email для восстановления'),fields=el('fieldset',undefined,'reception-fields'),email=field('Email','email'),proof=proofField();email.input.required=true;email.input.maxLength=254;fields.append(email.label,proof.label);submit(view,fields,'Подтвердить адрес',async()=>{await api('/api/admin/account/recovery',{email:email.input.value,currentPassword:proof.input.value});bind($('#admin-status'),'Письмо поставлено в очередь. Откройте ссылку из письма, чтобы подтвердить адрес.');});}
 async function recoverySettings(root){const config=await api('/api/admin/account/recovery'),card=el('article',undefined,'appointment');card.append(staticText('h3','Восстановление доступа'));if(config.enabled){card.append(config.email?el('p',config.email):staticText('p','Email не подтверждён'),button('Email для восстановления',recoveryEmail));}else card.append(staticText('p','Отправка Email ещё не настроена. Потребуются адрес отправителя и ключ почтового сервиса.'));root.append(card);}
 async function reminderSettings(root){const data=await api('/api/admin/reminders'),card=el('form',undefined,'appointment');card.append(staticText('h3','Напоминания клиентам'));const enabled=field('Отправлять напоминания по Email','checkbox');enabled.input.checked=data.settings.enabled;enabled.input.disabled=!data.settings.providerConfigured;card.append(enabled.label);const offsets=field('За сколько минут до визита (через запятую)','text',data.settings.offsets.join(', '));offsets.input.inputMode='text';card.append(offsets.label);if(!data.settings.providerConfigured)card.append(staticText('p','Сначала настройте почтовый сервис.','small-note'));card.append(staticText('p','Сервис может быть недоступен во время сна сервера. Время доставки не гарантируется.','small-note'));const save=staticText('button','Сохранить напоминания','button primary');save.type='submit';card.append(save);card.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{await api('/api/admin/reminders',{enabled:enabled.input.checked,offsets:offsets.input.value.split(',').map(v=>v.trim()).filter(Boolean).map(Number),revision:data.settings.revision});await render();}catch(error){fail(error);}finally{save.disabled=false;}});root.append(card,staticText('h3','История отправки'));const statuses={pending:'Ожидает',sent:'Отправлено провайдеру',cancelled:'Отменено напоминание',failed:'Ошибка доставки'};for(const job of data.jobs){const line=el('p',undefined,'small-note');bind(line,(t,lang)=>`${new Date(job.visit_start).toLocaleString(lang,{timeZone:'Asia/Baku'})} · ${job.offset_minutes} ${t('мин')} · ${t(statuses[job.state]||job.state)}`);root.append(line);}}
 async function businessSettings(root){const data=await api('/api/admin/business'),form=el('form',undefined,'appointment'),title=field('Название салона','text',data.name),phone=field('Основной телефон','tel',data.phone),online=field('Онлайн-запись открыта','checkbox'),cutoff=field('Отмена не позже чем за минут','number',String(data.cancel_minutes));title.input.required=phone.input.required=cutoff.input.required=true;title.input.maxLength=80;phone.input.maxLength=30;online.input.checked=data.online;cutoff.input.min='0';cutoff.input.max='10080';cutoff.input.step='1';const save=staticText('button','Сохранить данные салона','button primary');save.type='submit';form.append(staticText('h3','Данные салона'),title.label,phone.label,online.label,cutoff.label,save);form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{await api('/api/admin/business',{name:title.input.value,phone:phone.input.value,online:online.input.checked,cancel_minutes:Number(cutoff.input.value),revision:data.revision});await render();}catch(error){fail(error);}finally{save.disabled=false;}});root.append(form);}
 async function render(){const root=$('#settings-view');const [account,devices]=await Promise.all([api('/api/admin/account'),api('/api/admin/account/sessions')]);user=account.user;root.replaceChildren(staticText('h2','Доступ и безопасность'));const card=el('article',undefined,'appointment');card.append(el('strong',user.display_name||user.login),staticText('p',role(user.role)),button('Изменить пароль',password),button('Выйти на всех устройствах',()=>revoke()));root.append(card);
  const settings=el('form',undefined,'appointment'),privacy=field('Скрывать дату и время в Push','checkbox');privacy.input.checked=Boolean(user.push_private);const save=staticText('button','Сохранить уведомления','button primary'),message=el('p',undefined,'small-note');message.setAttribute('role','status');settings.append(staticText('p','Язык Push совпадает с языком панели.','small-note'),privacy.label,save,message);settings.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{const result=await api('/api/admin/account/preferences',{pushPrivate:privacy.input.checked});user=result.user;bind(message,'Настройки сохранены.');}catch(error){fail(error);}finally{save.disabled=false;}});root.append(settings);await recoverySettings(root);root.append(staticText('h3','Ваши устройства'));
  for(const device of devices.rows){const row=el('article',undefined,'appointment');row.append(bind(el('strong'),t=>device.device+(device.current?' · '+t('это устройство'):'')),bind(el('p'),(t,lang)=>t('Последняя активность: {date}',{date:new Date(device.last_seen).toLocaleString(lang,{timeZone:'Asia/Baku'})})),button('Завершить сессию',()=>revoke(device)));root.append(row);}
  if(user.role==='owner'){await businessSettings(root);await reminderSettings(root);const users=await api('/api/admin/users');root.append(staticText('h3','Сотрудники'),button('+ Добавить сотрудника',()=>editUser(),true));for(const employee of users.rows){const row=el('article',undefined,'appointment');row.append(el('strong',employee.display_name||employee.login),bind(el('p'),t=>`${t(role(employee.role))} · ${t(employee.active?'Доступ разрешён':'Отключён')}`),button('Настроить доступ',()=>editUser(employee)));root.append(row);}root.append(button('Журнал действий',()=>{auditOffset=0;return audit();}));}
 }
 async function init(request,onError,onLogout){generation++;api=request;fail=onError;signedOut=onLogout;user=(await api('/api/admin/account')).user;$('#tab-settings').hidden=false;for(const id of ['services','masters','rooms','revenue'])$('#tab-'+id).hidden=user.role!=='owner';if(user.language!==window.IlkerAdminI18n?.language)scheduleLanguage(window.IlkerAdminI18n.language);}
 function clear(){generation++;desiredLanguage=null;syncing=false;activeDialog?.close();$('#settings-view')?.replaceChildren();user=null;}
 return {init,render,clear,get owner(){return user?.role==='owner';}};
})();
